/**
 * Design-token pipeline: tokens/*.json → generated CSS.
 *
 * Run with --check to verify the committed CSS still matches tokens/*.json
 * instead of rewriting it. That mode exists because the generated files are
 * COMMITTED and are what the apps actually @import: without it, editing
 * tokens/color.json — the declared source of truth — is a silent no-op, and
 * the two can drift apart indefinitely with nothing to notice.
 *
 * Emits two artifacts consumed by every app's styles.css:
 *  - src/generated/tokens.css  — --atlas-* custom properties (:root light, .dark overrides)
 *  - src/generated/theme.css   — Tailwind v4 @theme block mapping utilities onto the vars
 *
 * Semantic tokens (bg/surface/text/text-muted/border) resolve to the light set at
 * :root and flip to the dark set under .dark — components only ever read semantics.
 */
import { mkdtempSync, readFileSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import StyleDictionary from 'style-dictionary';

const CHECK = process.argv.includes('--check');
const COMMITTED = 'libs/shared/design-tokens/src/generated/';
// In check mode build somewhere disposable, so a drifted tree is reported
// rather than quietly repaired — the whole point is to fail, not to fix.
const BUILD_PATH = CHECK ? mkdtempSync(join(tmpdir(), 'atlas-tokens-')) + '/' : COMMITTED;
const FILES = ['tokens.css', 'theme.css'];

const PREFIX = 'atlas';

const cssVar = (token) => `--${PREFIX}-${token.path.join('-')}`;

const SEMANTIC_KEYS = [
  'bg',
  'surface',
  'text',
  'text-muted',
  'border',
  // boundary of an interactive control — must clear 3:1 (WCAG 1.4.11),
  // unlike 'border', which only separates content
  'border-strong',
  // ink for text on the matching status tint — dark in light mode, light in dark mode
  'on-success',
  'on-warning',
  'on-danger',
  'on-brand',
  // the wash behind an overlay. Dark in BOTH themes on purpose: a scrim is a
  // shadow, not a surface, so it must recede the content under it. Using `text`
  // for this lightened the page in dark mode, which is the opposite effect.
  'scrim',
];

StyleDictionary.registerFormat({
  name: 'css/atlas-vars',
  format: ({ dictionary }) => {
    const all = dictionary.allTokens;
    const isMode = (t, mode) => t.path[0] === 'color' && t.path[1] === mode;
    const base = all.filter((t) => !isMode(t, 'light') && !isMode(t, 'dark'));
    const light = all.filter((t) => isMode(t, 'light'));
    const dark = all.filter((t) => isMode(t, 'dark'));

    const line = (t) => `  ${cssVar(t)}: ${t.$value ?? t.value};`;
    // semantic aliases: --atlas-color-bg etc. point at the active mode's values
    const semantic = (tokens) =>
      tokens
        .filter((t) => SEMANTIC_KEYS.includes(t.path[2]))
        .map((t) => `  --${PREFIX}-color-${t.path[2]}: ${t.$value ?? t.value};`)
        .join('\n');

    return [
      '/* generated by build-tokens.mjs — do not edit by hand */',
      ':root {',
      base.map(line).join('\n'),
      light.map(line).join('\n'),
      semantic(light),
      '}',
      '',
      '.dark {',
      dark.map(line).join('\n'),
      semantic(dark),
      '}',
      '',
    ].join('\n');
  },
});

/**
 * Tailwind v4 resolves `max-w-*`, `w-*`, `min-w-*` and friends against its
 * spacing namespace BEFORE its container namespace. So aliasing a token named
 * `md` into `--spacing-md` silently redefines `max-w-md` from 28rem to that
 * token's value.
 *
 * It did. `--spacing-md: var(--atlas-spacing-md)` (1rem) compiled to
 * `.max-w-md{max-width:var(--atlas-spacing-md)}`, which collapsed the audit
 * log's filter input — `<label class="mb-4 block max-w-md">` around a `w-full`
 * input — to 16px wide at every viewport, for months. The markup was correct
 * the whole time.
 *
 * Measured, not assumed: declaring the full `--container-*` scale explicitly
 * does NOT reclaim the utility. Spacing still wins. The only fix is to keep
 * these names out of the spacing namespace, which is why the emitter skips the
 * spacing group entirely.
 *
 * `--atlas-spacing-*` is still emitted in tokens.css and is still the documented
 * scale; it is reachable as `var(--atlas-spacing-md)`. No component consumed the
 * Tailwind alias (DESIGN.md records the scale as declared-but-unconsumed), so
 * dropping it costs nothing and removes a trap that was armed for every future
 * `max-w-sm`, `max-w-lg`, `w-xs`, and so on.
 *
 * `radius` is NOT affected and is still emitted: `rounded-*` reads only
 * `--radius-*`, and these keys carry Tailwind's own meaning there.
 */
const SHADOWED_NAMESPACE = 'spacing';
/** Tailwind's container-scale keys — a token aliased to one of these under `--spacing-*` steals it. */
const TAILWIND_CONTAINER_KEYS = [
  '3xs', '2xs', 'xs', 'sm', 'md', 'lg', 'xl',
  '2xl', '3xl', '4xl', '5xl', '6xl', '7xl',
];

StyleDictionary.registerFormat({
  name: 'css/atlas-tailwind-theme',
  format: ({ dictionary }) => {
    const all = dictionary.allTokens;
    const entries = [];
    for (const t of all) {
      const [group, ...rest] = t.path;
      if (group === 'color') {
        if (t.path[1] === 'light' || t.path[1] === 'dark') continue; // semantics cover these
        entries.push(`  --color-${rest.join('-')}: var(${cssVar(t)});`);
      } else if (group === 'spacing') {
        // DELIBERATELY NOT EMITTED. See SHADOWED_NAMESPACE below: aliasing these
        // into Tailwind's `--spacing-*` made `max-w-md` resolve to 1rem.
        continue;
      } else if (group === 'radius') {
        entries.push(`  --radius-${rest.join('-')}: var(${cssVar(t)});`);
      }
    }
    for (const key of SEMANTIC_KEYS) {
      entries.push(`  --color-${key}: var(--${PREFIX}-color-${key});`);
    }

    // Fails the build rather than shipping a shadowed utility. The bug this
    // catches is invisible in review (the markup looks right), invisible to
    // tokens:check (the CSS matches the JSON), and invisible to the detector
    // (it has no element-sizing rule). It has to fail here or not at all.
    const stolen = entries
      .map((line) => line.match(/^\s*--spacing-([^:]+):/)?.[1])
      .filter((key) => key && TAILWIND_CONTAINER_KEYS.includes(key));
    if (stolen.length) {
      throw new Error(
        `build-tokens: ${SHADOWED_NAMESPACE} token(s) "${stolen.join('", "')}" would shadow ` +
          `Tailwind's container scale, silently redefining max-w-${stolen[0]} and friends. ` +
          'Rename the token or keep it out of the Tailwind theme.'
      );
    }

    return [
      '/* generated by build-tokens.mjs — do not edit by hand */',
      '@theme inline {',
      entries.join('\n'),
      '}',
      '',
    ].join('\n');
  },
});

const sd = new StyleDictionary({
  source: ['libs/shared/design-tokens/tokens/*.json'],
  platforms: {
    css: {
      // full-path kebab names keep token names unique (both formats read `path` anyway)
      transforms: ['name/kebab'],
      buildPath: BUILD_PATH,
      files: [
        { destination: 'tokens.css', format: 'css/atlas-vars' },
        { destination: 'theme.css', format: 'css/atlas-tailwind-theme' },
      ],
    },
  },
});

await sd.buildAllPlatforms();

if (!CHECK) {
  console.log('tokens built: src/generated/{tokens.css,theme.css}');
} else {
  const drifted = FILES.filter(
    (file) => readFileSync(join(BUILD_PATH, file), 'utf8') !== readFileSync(join(COMMITTED, file), 'utf8')
  );
  rmSync(BUILD_PATH, { recursive: true, force: true });
  if (drifted.length) {
    console.error(
      `\u2716 generated CSS is out of date with tokens/*.json: ${drifted.join(', ')}\n` +
        '  run: pnpm exec nx run shared-design-tokens:build-tokens'
    );
    process.exit(1);
  }
  console.log(`\u2714 generated CSS matches tokens/*.json (${FILES.join(', ')})`);
}
